"""Bundled notification sounds (generated by tools/make_sounds.py - original synthesis, no third-party audio)."""
from __future__ import annotations

from pathlib import Path
from typing import List, Optional, Tuple

SOUNDS: List[Tuple[str, str, str]] = [
    ("soft", "Soft", "Gentle two-note chime"),
    ("classic", "Classic", "Short traditional bell"),
    ("focus", "Focus", "Rising four-note phrase for focus sessions"),
    ("alarm", "Alarm", "Repeated two-tone pulses"),
]
NAMES = [s[0] for s in SOUNDS]


def assets_dir() -> Path:
    here = Path(__file__).resolve()
    for base in (here.parents[2] / "assets", here.parents[1] / "assets", Path.cwd() / "assets"):
        if (base / "sounds").is_dir():
            return base / "sounds"
    return here.parents[2] / "assets" / "sounds"


def path_for(name: str) -> Optional[Path]:
    p = assets_dir() / f"{name}.wav"
    return p if name in NAMES and p.is_file() else None


def label(name: str) -> str:
    return next((l for n, l, _ in SOUNDS if n == name), name)
